using Network.Management.App.Models.DTOs;

namespace Network.Management.App.Services
{
    public interface ILogService
    {
        /// <summary>
        /// Returns logs filtered by the allowed categories. When <paramref name="category"/>
        /// is provided it must be one of the allowed categories, otherwise it is ignored.
        /// </summary>
        Task<IEnumerable<LogDto>> GetLogsAsync(IEnumerable<string> allowedCategories, string? category = null);

        /// <summary>Returns all logs generated by a specific user.</summary>
        Task<IEnumerable<LogDto>> GetLogsByUserAsync(int userId);
    }
}
